create or replace function public.sales_charge_catalog_save_v610(p_tenant_id uuid,p_charge_id uuid,p_code text,p_name text,p_service_variant_id uuid) returns uuid language plpgsql set search_path=public,private,pg_temp as $$ declare v_id uuid; begin if p_charge_id is null then insert into public.sales_charge_catalog_v610(tenant_id,code,name,service_variant_id) values(p_tenant_id,upper(trim(p_code)),trim(p_name),p_service_variant_id) returning id into v_id; else update public.sales_charge_catalog_v610 set code=upper(trim(p_code)),name=trim(p_name),service_variant_id=p_service_variant_id,updated_at=now() where id=p_charge_id and tenant_id=p_tenant_id returning id into v_id; end if; return v_id; end; $$;;
